/**
 * 섹션 2 · 유닛 1 — 이분은 누구세요?
 * 출처: 서울대 한국어 1B 9과
 *
 * 배우는 것
 *   가족        할머니·할아버지·어머니·아버지·형·오빠·누나·언니
 *               남동생·여동생·아내·남편·딸·아들·부모님
 *   수(고유어)   열·스물·서른·마흔·쉰·예순·일흔·여든·아흔·백  ·  N 살 · N 명
 *   높임말       연세·성함·댁·분  ·  계시다·드시다·주무시다
 *   문법        N(의) N   ·   N을/를 잘하다[잘 못하다·못하다]
 *               N(이)세요  ·   A/V-(으)시-
 *
 * 섹션 2 규칙 (섹션 1과 달라지는 것)
 *   - 다중 빈칸(sentenceTemplate)과 타이핑 계열이 열린다.
 *     다만 이 유닛은 어휘·높임말이 한꺼번에 들어와서 부담이 크므로 아직 쓰지 않는다.
 *     타이핑은 유닛 3부터 한 단어씩 넣는다.
 *   - reply_builder 는 계속 대화 레슨에만 하나씩.
 *   - word_matching / audio_match 는 짧은 단어만, 항상 5쌍.
 *   - speaking 은 한 사람이 말하는 문장만, 16자 이내.
 *   - 같은 타입을 연달아 두지 않는다.
 *
 * 이 유닛의 함정 — 오답 보기로 매번 판단하게 만드는 것
 *   1. 화자 성별      남자는 형·누나 / 여자는 오빠·언니
 *   2. 높임 여부      나이↔연세 · 이름↔성함 · 있다↔계시다 · 먹다↔드시다 · 자다↔주무시다
 *   3. 받침 → (으)시  가세요(O) 가으세요(X) · 읽으세요(O) 읽세요(X)
 *   4. 세는 단위      네 명(O) 네 살(X) — 사람은 명, 나이는 살
 *   5. 줄임말         저의=제 · 나의=내 (제의·내의 는 없다)
 */

